import type { MeaningPack } from '../../types';

export const enHksB: MeaningPack = {
  lang: 'en',
  texts: {
    'harikathamrutasara-13': {
      summary: "Sandhi 13 (Nama-smarana, remembering the Lord's name): remembering Hari in every state of life, even in play, yawning or bathing, frees one from sin and from Yama's messengers. One should know Hari as the doer of all deeds, offer all actions to him, and see worship of the gods and of the wise as worship of him through his images. He dwells in the elements, rain, forest and water, and gives each being the tastes fit for it; this secret is to be told only to true devotees.",
      verses: {
        '0.0': "By the grace of the guru, I shall tell the nectar-essence of Hari's stories; devoted devotees of the Lord, listen to this with reverence.",
        '0.1': "Whether playing with children, delighting with his wife, riding in procession on a horse, palanquin, elephant or other mount, or even hiccuping and yawning, the man who remembers Krishna, Devaki's son, never falls into the hands of Yama's messengers, wherever you look.",
        '0.2': "Whether in fine clothes, over a letter, in joy, anger or forgetfulness, if one just once opens the mouth and says the two syllables \"Hari\", the sins burn away at once, like fire entering a heap of cotton.",
        '0.3': "While lying down or getting up, sitting and talking, working at home, bathing or eating, the Lord who is far from all impurity stays beside the one who in every place thinks of his name and form; he does not leave him even for half a moment.",
        '0.4': "Whatever family he was born in, whatever country he lives in, whatever deed he does, at whatever time: for the wise who always and everywhere contemplate and worship Lakshmi's Lord and rejoice, what fear, grief or other faults can there be?",
        '0.5': "One who can swim in the ocean of Vasudeva's qualities crosses the ocean of worldly life quickly and without effort. But the one who longs for evil sense objects, never tiring of them, suffers many kinds of trouble, because he does not see the good path of devotion.",
        '0.6': "Of what use are bathing, japa, worship of the gods, discourses, and the telling and hearing of the Mahabharata and the great Upapuranas day after day, if a man does not offer all the deeds done by his senses of knowledge and action as worship of Lakshmi's Lord? (The sentence is completed in the next verse by its contrast.)",
        '0.7': "Can one who is in the heavenly Ganga have heaps of sins? Can snakes fear anything in Garuda's abode? In the same way, one who forgets the jiva's claim to be the doer and knows that the Lord of all, high and low, is the doer will not be stained by any action he performs.",
        '0.8': "The lowest is the one who says \"I do whatever merit and sin there is\": he is fit for bad deeds. The middling man is the one who says Hari is the doer of the merit. The best of men is the one who always, with love, thinks of Srinivasa as the doer of both the good and the bad (the pairs of opposites) and is happy.",
        '0.9': "In this world it is the gods, and not mere men, who are the objects of worship. However it is done, worship of them is worship of Hari, for they are called mere images of the Lord who delights Rama (Lakshmi). Their favour is counted as the Lord's own favour for those fit for liberation.",
        '0.10': "The wise call a fool (cow-donkey) the one who says \"I am the body\", who says wife, sons, house and wealth are his own, who says only waters like the Ganga are true holy waters, who says worship of fire, metal and such symbols is the only worship of God, and who says that good people are mere humans.",
        '0.11': "The gods who preside over fire, moon, sun, stars, earth, the Ganga and other chief holy waters, and over wind, sky, mind and the other senses do not purify those who fail to worship them the way the wise do, with a clear and good mind. Is merely performing their worship enough?",
        '0.12': "Touching a burning coal, whether you saw it or not, it burns just the same. In the same way the crowds of devotees, who are as bees at the spotless lotus feet of the lotus-eyed Lord, purify at that very instant, by a mere look, a man who throws himself down before them.",
        '0.13': "Therefore keep the company of the wise again and again; do not mix with wicked people. Without going mad over worldly life, move about meditating everywhere on the name and form of Hari, who is carried on Garuda's shoulder, and give up all other thoughts.",
        '0.14': "Within this universe, born of the lotus, he dwells in all beings without a break and carries out their knowing activities, without letting them know. The man who sees nothing and says \"I do all the deeds\" falls into an evil birth; the one who says \"Hari is the doer\" is liberated.",
        '0.15': "Do the water creatures that live in the Ganga, the river that removes the dirt of the Kali age, know the greatness of that holy water? In the same way, even Brahma, Vayu, Shiva and other gods, made mighty in many ways by Hari's grace, do not know the stainless qualities of the Infinite One.",
        '0.16': "Lakshmi's Lord, dwelling in the lotus of the heart, deludes all beings, binds them with the three gunas, makes them delight in gross action, and, without revealing his lovely sports, keeps turning people round in worldly life like a potter's wheel.",
        '0.17': "To those who study the Veda and the scriptures, give up forbidden acts and do good deeds daily, he gives the pleasures of heaven and the like; he sends sinners to hell; he gives people their sorrows and joys; and he makes wicked debaters taste great suffering in blinding darkness.",
        '0.18': "To one who worships him as free of the gunas, the compassionate Lord gives happiness in liberation without the faults that come with contact with the gunas, and protects him. To the followers of the three Vedas, who find him hard to reach, he who is beyond the three gunas gives constant travel through heaven, earth and hell.",
        '0.19': "Though he dwells within the three kinds of beings, pleasure and pain never touch him: he is the purifier of purifiers, supreme, an ocean of perfect bliss. In this egg of the lotus-born Brahma he makes his own body take the form of the universe, and the Lord of high and low protects all worlds, moving and unmoving.",
        '0.20': "Forgetting the notion of independent, uncaused doership, and knowing that Hari, dwelling within and without, does everything himself, move about fearlessly like a rutting elephant. He who is worshipped by Vayu does not leave you even for half a moment.",
        '0.21': "Without wearing out the body by performing many rites, daily worship the form of Hari who shines in the pure abode of your heart. Without understanding this way of worship, mere offerings of fruit, flower, water and tulasi leaves are not accepted by Vasudeva.",
        '0.22': "He is Narayana in the earth, the one called Turiya in water, Sankarshana in fire, Pradyumna in wind, and Aniruddha in the sky. Taking these five forms, he has the elements called by his own names and comforts his creatures.",
        '0.23': "As Narayana he is in the cloud and has it called by his name; as Vasudeva he dwells in the water in the cloud's womb; Sankarshana is the thunder and roar, Pradyumna the lightning, and Aniruddha is in the drops of rain, so that he is known as the rain.",
        '0.24': "People are tied to house, family, wealth and the like; not knowing what is allowed and forbidden or which deeds are good, they spend their days given to eating, sex and sleep. Not knowing the Lord who dwells in the cave of the heart, all beings suffer in worldly life.",
        '0.25': "Together with Brahma, Garuda, Shesha and Shiva he lives in the forest as well. Giving growth through the moon, he protects the bodies of birds, beasts and snakes, in forms bearing the names fitting each of those creatures.",
        '0.26': "Of boundless glory, he protects in the forest as Narasimha, in all places as Keshava (the Lord who measured the earth), in the sky as the lord of the sky, and in the water as the great fish; the merciful Lord guards his devotees sincerely, day after day.",
        '0.27': "(The text of this verse is partly garbled.) It speaks of Hari as the inner controller of all causes, of his gross incarnations, and of the six tastes offered to him. The clear instruction is: without disclosing this secret, always remember the form and qualities of the Lord of boundless glory and be happy.",
        '0.28': "As water creatures, happily thinking \"we shall eat the reflection\", keep trying every day, so people, not knowing the true abode (the original) of all enjoyable tastes in Krishna, Balarama's younger brother, worship other things and long for the goals of life. (Bimba is the original, pratibimba the reflection.)",
        '0.29': "Gods, sages, gandharvas, ancestors, humans, kings, demons, cows, goats, donkeys, sheep and all other beings: Lakshmi's Lord, dwelling within each of their limbs, accepts the tastes they enjoy, and always feeds each group of beings the tastes that suit it.",
        '0.30': "Give up a coarse mind, drop worldly gossip, know gold, cloth and clods of earth to be alike, and keep thinking at every step: the Lord who holds the whole universe in his belly dwells in all and does their deeds.",
        '0.31': "When people in the world are spoken to with stinging words, they cannot bear it and strike in great anger. But even when called \"killer of your uncle\", \"paramour\" or \"butter-thief\", the merciful Lord takes into his own abode and comforts those who say so.",
        '0.32': "Saints should always listen to this Harikathamrita-sara; do not tell it to the harsh, to slanderers or to the unfit. Teach this secret to the supreme devotees of the Lord, who with true devotion praise his deeds and rejoice.",
        '0.33': "Knowing that the Lord of true resolve, always to be praised, is the supreme goal, enjoy life while remembering him with the greatest joy. Jagannatha Vithala, full of eternal bliss and the best of friends, dries up the ocean of worldly life and grants the manifestation of conscious bliss.",
      },
    },
    'harikathamrutasara-14': {
      summary: "Sandhi 14 (Pitrigana-vichara, the ancestors): the Lord, in ninety-six names and thousands of forms, dwells within the gods who stand for the ancestors (Vasus, Rudras, Adityas), within the offerings and within every eater and every thing eaten, and accepts what his devotees offer. He gives the ancestors lasting happiness, protects devotees' observances, and is the one source of every deed. The sandhi also teaches the five differences (between Hari and jiva, Hari and matter, jiva and jiva, jiva and matter, matter and matter), the reflection (pratibimba) relation of the world to Hari, and the care needed in whom this secret is told to.",
      verses: {
        '0.0': "By the grace of the guru, I shall tell the nectar-essence of Hari's stories; devoted devotees of the Lord, listen to this with reverence.",
        '0.1': "(The text of this verse is partly unclear.) The Lord of Kriti and Jaya, in his forms such as Pradyumna and Vasudeva within the three kinds of ego, is called the thing enjoyed in twenty-four forms; and dwelling in fire and the senses, within the enjoyers, he is called the enjoyer in thirty-three forms.",
        '0.2': "(The text of this verse is partly unclear.) In thirty-odd forms he dwells in the sun, friend of the lotus. Vasudeva, Lord of Maya's consort, is named Time among the three kinds of ancestors; Aniruddha, not showing himself within the Vasus, Rudras and Adityas, is called the doer, the deed and the act.",
        '0.3': "The self-ruling Narayana, calling himself by ninety-six names and dwelling within the Vasu, Rudra and Aditya and within doer, deed and act, accepts without any pretext the service his own people daily do, and gives their ancestors endless happiness.",
        '0.4': "Like threads in cloth, Lakshmi's Lord in a fivefold form ever dwells in the doers, Vasu, Rudra and the Sun. Madhva, the teacher, in whom the Lord dwells as inner Self, comforts the saints who think of him, granting all they desire here and hereafter.",
        '0.5': "Those who, to please their father and mother, give up blameworthy acts and, without breaking any prescribed duty, perform rites with all their parts are worthy of respect. On earth they live daily in divine and bodily comfort, long-lived and renowned.",
        '0.6': "Those who, with remembrance of Janardana the inner Self, rightly know the gods led by Brahma, the swan-rider, who hold the Lord's three portions, and who, knowing his three sets of thirty-six forms, worship him who is borne on Garuda's shoulder, are the ones who are fulfilled.",
        '0.7': "In three thousand five hundred and fifty-five forms Janardana, the foe of Khara, protects in many ways, so that no obstacles come to the great feasts the learned perform, dwelling in all the bodies and being called by their names.",
        '0.8': "Victory, victory to Jaya's Lord, Dattatreya, Kapila, Mahidasa, dear to devotees, the ancient Person, full of bliss, a mass of knowledge, Hayavadana, Hari, Hamsa, unlike the three worlds, the support of the whole universe, free from ills: with grace protect us. Thus one should pray.",
        '0.9': "The Lord, worthy of praise even by Akshara (Lakshmi), has himself called by the ninety-six names; the ocean of mercy, friend of the learned, accepts the holy rites his own people perform with true devotion and protects them in many ways, a boat across the ocean of worldly life.",
        '0.10': "(The text of this verse is partly unclear.) He who gives bodies, will he not give each its food? Praised by the good, of auspicious deeds and ever full of virtue, he gives happiness in this world and the next; bearing the mountain on his back as the Tortoise, he gave the nectar to Brahma and the other gods and crushed their enemies.",
        '0.11': "To Brahma and the other gods the Lord of Maya's consort himself becomes Svaha (the gods' offering) and satisfies them at all times. As Sankarshana he becomes Svadha, the offering to the ancestors; and Pradyumna and Aniruddha are the fruits and grass born of the earth.",
        '0.12': "He is the food for men and animals. Without letting those devotees who worship him in this way within the golden egg suffer, Hari carries them across the high ocean of worldly life and gives them the happiness of seeing the Self, he who is the fourfold food.",
        '0.13': "When, with true devotion, one offers the food, saying \"this food is for Narayana who dwells in Vayu; I offer it to Krishna\", along with the fitting and unfitting daily acts done by mind, speech and body, the merciful Lord accepts it and comforts the giver.",
        '0.14': "After hearing from the learned the account of the seven kinds of food, remember and worship the forms beginning with Aniruddha at the proper times, without laziness; and do not tell this to dull minds. Lakshmi's Lord himself is both the food and the eater.",
        '0.15': "Knowing this, offer the seven foods daily to Govinda without forgetting, fearlessly, as the great sacrifice. The Lord of Indira accepts them, and without being asked brings eagerly to his servants the supreme good.",
        '0.16': "Like the man who says he will win a battle holding a needle, the ignorant of this world, not worshipping with devotion and knowledge the lotus feet of the Lord of the universe, long for dharma, wealth and pleasure and only suffer.",
        '0.17': "The destroyer of the cart, being near all beings yet not revealing himself to the world, does all actions and has them done. Guileless, he gives happiness to devotees at all times. Alas, what can I say of his great glories!",
        '0.18': "Lakshmi's Lord, who is in Vaikuntha, dwells within Pranava (Om), Prakriti, Brahma and the other conscious beings. As the root cause, playing in his sports under the names of his portions without showing himself, he stays hidden in the three places, like ghee in milk.",
        '0.19': "In the three yugas the original Lord, to protect the wise, destroy the sons of Diti and preserve dharma, came down compassionately on earth with his own retinue and showed all beings many kinds of human-like conduct.",
        '0.20': "(The last line is unclear.) Dwelling in Prakriti, called the cause, he made the twenty-four principles, took on their forms and names, built the egg of the lotus-born Brahma, and shows himself day by day in the forms called effects.",
        '0.21': "The inner controller of the jivas, the whole of whom each part is a portion, he dwells in bodies and senses, and daily takes in objects under the names of his portions. Enjoying these objects himself in bliss, he gives to gods, men and demons without a break their happiness and the sorrow of worldly life, he the friend of Sudhama.",
        '0.22': "Without wearing out the body wandering from land to land, and without falling into the false hope of rites done for desire, all beings from Brahma downward should know earth, water, fire, wind, sky and all the principles to be the seat of the Supreme Lord, and worship him unceasingly.",
        '0.23': "There are two kinds of beings in the world: kshara and akshara (the perishable and the imperishable), those with and without the subtle body, the created and the uncreated. Inert Prakriti is called by names like Pranava, Akshara, Mahat, Anu and Kala. Remember everywhere the fivefold difference (panchabheda), together with Hari.",
        '0.24': "The difference between jiva and jiva, between matter and matter, between jiva and matter, and the Supreme Lord is different from both jiva and matter (together with the difference between him and jiva, and him and matter, these are the five differences). Knowing this daily, and seeing the five differences everywhere in this egg of Brahma and in the body, quickly reach Achyuta's feet.",
        '0.25': "(The text of this verse is partly unclear.) At the beginning the two groups kshara and akshara are named: Rama and Madhusudana under the akshara, and Prakriti, Pranava and Kala under the kshara. Knowing the differences among the jivas from Brahma down to a blade of grass, do not teach this secret to the dull, but meditate on it everywhere.",
        '0.26': "As lamps lit from a lamp drive away the darkness in a shop and show what is there, so the Lord who rides Garuda, pervading all places in many forms and names, shows as much of his greatness as he wishes, without making it known who it is.",
        '0.27': "As a rainbow is reflected in relation to the sun, the three worlds shine in Hari as his reflection (pratibimba, image of an original, bimba), with no limiting condition between. Knowing this, meditate daily on the very auspicious form of Prahlada's protector, who shines in the heart in every place.",
        '0.28': "As a very clean white cloth soaked in a special liquid and put in fire gives out light everywhere without dimming, great souls soaked in the sweet nectar of devotion to Rama, the destroyer of Trishira and Dushana, are not troubled by heaps of sin even while living in worldly life.",
        '0.29': "As rivers flow separately and ceaselessly into the ocean and remain happy, the forms of Lakshmi, who presides over the three gunas, appear in Hari at all times without any conflict among them.",
        '0.30': "If the owl cannot enjoy the sight of the sun, the friend of the lotus, when he rises, is the sun at fault? So too, if the ignorant cannot accept Jagannatha, Lakshmi's Lord, and be happy, what does their blame matter? Will the wise not be glad to hear this poem?",
        '0.31': "Jagannatha Vithala, the inner Self of Vayu, the Guru, constantly pervades the sentient and the insentient without making himself known; he makes the demons restless for sense objects and deludes them. He is fearless, ever blissful, faultless and blameless. (The verse ends without completing the sentence.)",
      },
    },
    'harikathamrutasara-15': {
      summary: "Sandhi 15 (Shvasa, the breath): Vayu (Bharatisha), dwelling in every being, performs by Hari's command 21,600 breath-japas a day (360 in each ghalige, a 24-minute unit), and the sandhi counts them for each watch of the day, fortnight, month, season and year. Without knowing this, empty rites achieve little. It also teaches that Hari is within the elements, food, water and fire, that the liberated enter his city by five gates guarded by various gods, that the world is Hari's reflection, and that worshipping even one quality of his with devotion fulfils the devotee.",
      verses: {
        '0.0': "By the grace of the guru, I shall tell the nectar-essence of Hari's stories; devoted devotees of the Lord, listen to this with reverence.",
        '0.1': "Bharatisha (Vayu), dwelling in all beings, performs in each ghalige (24 minutes) three hundred and sixty japas without tiring. Merciful, all-knowing and the giver of all that is wished, he completes each one's spiritual practice and sends beings to earth, heaven or hell.",
        '0.2': "(The verse breaks off unfinished.) Active among the masses of beings day and night, ever awake and without the least fatigue, he nourishes them; unseen, he stays at the root of the lotus feet of the Lord, the source of all.",
        '0.3': "It is known that in one yama (three hours) there are 2,700 breaths; for the second yama, 5,400; for three yamas, 8,100; and for twelve hours, 10,800.",
        '0.4': "In one day it comes to 21,600. By Mukunda's command Vayu does these himself and has them done and so protects the worlds: keep praising him thus and never forget it. Do Indra and the others, however you look, have this greatness at any time?",
        '0.5': "For a fortnight the count is 3,24,000, and for a month 6,48,000 (japas). Maruta, performing them, ferries good people across the ocean of worldly life and protects them, giving many enjoyments. (The last words are cut off.)",
        '0.6': "For two months, a season (ritu), the count is 12,96,000, as the learned know the breath-japa; for an ayana (half a year) it is 38,88,000, as the wise know.",
        '0.7': "For a year it is double that. The Guru Vayu does and has all these japas done, removing the sins of the good who think of him. Dwelling even in the enemies of the gods, those who are destined for darkness, he practises the \"soham\" (I am He) worship in their way.",
        '0.8': "While Vayu does this much worship in all beings, what is the use of bathing without reflection in any water you see, sitting daily in the house on a black-antelope skin or other seat as a fine good man, and tirelessly counting rosary beads?",
        '0.9': "(On dissolution.) Food and water both merge in fire, and their presiding deities Shiva and Pavana (Vayu) come under Rama's (Lakshmi's) control. She, together with these gods, reaches Sri Madhusudana. Knowing this, give food and water with reverence, eat and be happy.",
        '0.10': "Just as goats and sheep that have browsed on thorny babul leaves still give milk freely, the merciful Lord, the Lord of Lakshmi, dark as the blue lotus, Sri Rama, accepts even the poor deeds of his own people and protects those he has placed in his abode.",
        '0.11': "(The text of this verse is partly unclear.) In the moon, sun and fire, in their black, white and red aspects, dwell Shiva, Vayu and Lakshmi, and within these three Sri Krishna, Hayavadana. The merciful Lord, as the threefold one, protects all beings on earth under the names Food, Water and Fire.",
        '0.12': "(The verse is cut off.) Like a man who holds a lamp in his hand yet, not seeing, falls into a well, are all those who daily expound the Vedas and the great Upanishads but do not know the working of the Lord's pure forms praised by Shri and Vayu, and who say the jiva is the doer of merit and sin, instead of Hari the real doer.",
        '0.13': "Vayu, made of speech and mind, dwelling in Agni, Varuna, Indra and the other gods, remembers and utters the Lord's forms and qualities again and again, and so always comforts us. His lotus feet are worshipped by hosts of sages.",
        '0.14': "Speech and mind are the two feet (of his working); dwelling in these two as Sankarshana, the protector of Prahlada reflects, in the form of dialogue, on the Vedas, shastras and puranas, and gives joyful happiness, protecting all good people.",
        '0.15': "As the wind carries the lotus fragrance in all ten directions and moves about giving pleasure to the nose, so daily praise Indiresha's good qualities and rejoice in them, while among foolish people remain as if blind, deaf and mute.",
        '0.16': "At the east gate of Shri's Lord's palace, the best of humans, reaching Lakshmi-Narayana within Prana (Vayu, Bharati's lord), where the sun with Samjna stands, rejoice in liberation, praising the incarnations and qualities of Narayana who is in every body.",
        '0.17': "At the south gate of the city of the Lord whom Pranava expounds, the hosts of ancestors, praising the form and qualities of Pradyumna (with Kriti), who dwells in the vyana breath where the moon with Rohini stands, roam as they wish in Gadadhara's spotless city.",
        '0.18': "(The text of this verse is partly unclear.) At the west gate of the abode of the Lord of measured valour, the sages, with their wives, praise the Lord's qualities with delight and gladden the gods; they meditate in the lotus of their own heart on Sankarshana and rejoice.",
        '0.19': "Tumburu and all the gandharvas, who sing the qualities and form of Shri's Lord in the seven notes, along with Indra and Shachi, the gate-keepers of the north gate of Ramapati's city, reach Aniruddha, lord of Shanti, who is emerald-hued and dwells in the samana breath.",
        '0.20': "Garuda, Shesha, Indra and the other gods, down to Pushkara, who stand at the upper gate, together with Bharati in the udana breath, reach the abode of the very auspicious limbs of Maya-Vasudeva who shines there, and ever rejoice in seeing Mukunda.",
        '0.21': "Rama's Lord, the inner Self of the gate-keepers of the five gates and of Bharati and Prana, comes in five forms to each gate. Those who know the taratamya (the graded order of ranks) among the five kinds of beings fit for liberation, Kamsari (Krishna) ferries across the ocean of worldly life and makes them liberated.",
        '0.22': "Wash the body, adorn it with the sacred name-marks (nama-mudra), and please the Lord every day, as a polished vessel shines to the onlooker. The person who, through false arguments and the reasoning of the ignorant, does not know the heart of the scriptures, gains nothing by merely doubting this.",
        '0.23': "As waves rise in the ocean, countless incarnations of the Lord of the lotus navel, Hamsa, Udgitha, Hayavadana, Krishna and others, ever abide in him, and the forms present in the conscious hearts of all beings abide in him without a break.",
        '0.24': "As sea creatures such as crocodiles move and rejoice in the same way day and night, the three worlds stay in the belly of the Lord of the universe. They are called his reflection (pratibimba) and always bear Hari's names and forms.",
        '0.25': "As a child in the womb grows day by day when its mother eats fine foods, so the Lord with the lotus navel feeds all tastes to the jivas and protects them: father of Ganga (Hari), far from birth and every other fault, profound.",
        '0.26': "One who is a slave to desire becomes a servant of other people, but all become servants of the man who has made desire his own servant. If one worships the lotus feet of Shri's Lord without desire, Hari, ocean of mercy, is pleased and gives himself along with Rama.",
        '0.27': "As a man who, without seeing the whole length of the Ganga from end to end, bathes in it at one place is freed of all faults, so the great soul who worships one single quality among the Lord's spotless and infinite qualities is called blessed and fulfilled.",
        '0.28': "(The verse breaks off.) Vasudeva is called the cotton plant; Sankarshana is the cotton wool, Pradyumna the thread, Aniruddha the cloth, and Narayana, the supreme Lord, shines as the ornament, always worthy of honour and the giver of honour.",
        '0.29': "Jagannatha Vithala, the four-formed, dwells with his consort in cloth as warp and weft. Knowing that he guards you every moment from cold, sun, rain and wind, always worship the inner Self of all on this earth.",
      },
    },
    'harikathamrutasara-16': {
      summary: "Sandhi 16 (Datta-svatantrya, the independence given by Hari): Hari alone is fully independent; out of his own independence he grants a measured portion to every being by rank, from Lakshmi, Brahma and Vayu down to the demons, and works through them all. He moves each jiva by its fitness and karma, takes the good deeds of the devotionless and gives them to the surrendered, and carries across the ocean of worldly life those who accept their dependence on him. The claim \"I am independent\" is mocked. The sandhi ends by defending a devotional poem in the people's language and with the poet's humility.",
      verses: {
        '0.0': "By the grace of the guru, I shall tell the nectar-essence of Hari's stories; devoted devotees of the Lord, listen to this with reverence.",
        '0.1': "(The figures in this verse are unclear.) The merciful Hari, out of the measureless independence that is in him, took out a part and gave a fixed portion to Lakshmi, and divided in this way the three quarters (padas) within his own body, he who is called Tripada.",
        '0.2': "The faultless Lord placed fifty-two of those portions in Brahma, lord of Satyaloka, forty-eight in Vayu, twenty in Shiva, fifteen in Kama and Indra, ten in the gods who preside over the principles (tattvas), and ten in all other jivas.",
        '0.3': "Among all the demons, beginning with Kali, he placed forty-five. Knowing this, worship him with supreme devotion and never forget it; move about on earth knowing that Lakshmi's Lord is with you in every place and comforts you like a friend.",
        '0.4': "As a king gives authority and ownership to his ministers and has the royal work done through them, so the Lord, praised by poets, places his portions in gods, demons and humans, and constantly does and has done the deeds born of the three gunas.",
        '0.5': "In the same way the ocean of mercy, having placed merit and sin in gods, demons and humans, makes their fruits go as they should: he takes the good deeds of the devotionless, which are praised, and gives them to the surrendered, making those happy; he of the fine arms.",
        '0.6': "As a shopkeeper who has taken a ruby from a customer pacifies him by giving something paltry, the Lord, himself the master of every sacrifice, takes the fruit of the gifts, sacrifices and other acts the demons perform daily, gives them improper pleasures, and makes the demons drunk with delusion.",
        '0.7': "As the moon, marked with a deer, grows by degrees with its spotless rays and breaks the darkness that stops people seeing, so for great souls who meditate on the form of the Lord borne on Garuda's shoulder, knowledge, devotion and the rest grow and give happiness.",
        '0.8': "As a king does not count the faults of a thief who brings stolen wealth to him and protects him, but punishes the one who does not give it up, so the Lord accepts all deeds, fit or unfit, when they are offered with \"Krishnarpana\", places the giver in his own house and gives him joy: Madhava, loved by those who bow.",
        '0.9': "Entering the jivas as food, as described before under the names Anna and Annada (the food and the eater), he does and has done their activities without being troubled, makes them praised as blessed, and is himself called by each of those names, though free from the three gunas.",
        '0.10': "(The last line is cut off.) Water, when it falls, takes the form of what it falls on. In the same way, when well-born people worship the remover of the dirt of the Kali age, their wrong deeds become faultless deeds and give them the goals of life.",
        '0.11': "Like a mother who puts her face to the child's face and kisses it, hugs it tight, and lovingly takes out her breast to feed it, the immeasurable Lord brings himself to the devotees who meditate on his lotus feet, and gives them happiness everywhere.",
        '0.12': "As a gardener, wishing the seed to take root in the soil, lovingly lifts water in a pot and tends the saplings, the horse-faced Lord (Hayagriva) creates jivas in the world without any strain and protects them at all times, never letting them go beyond their fitness.",
        '0.13': "As a thirsty man who has water in the ground beside him forgets it, lifts his face and writhes, looking for it in the sky in all eight directions, so the deluded, not knowing that Shri's beloved is the inner controller of all, daily worship other gods with devotion.",
        '0.14': "The chief fruit is Vaikuntha; the middling fruit is the worlds from Mahar upward; the lowest fruit is worldly enjoyment. Knowing this, worship the foe of the demons with great devotion and be free of sorrow always. The Lord, father of Bharatisha, loving to his devotees, never abandons those who take refuge in him.",
        '0.15': "(The end of the verse is cut off.) As a mother gives a child sick with disease sweet water and a medicine ground in water, so omniscient Badarayana (Vyasa), out of grace to devotees, said in the Bhagavata and elsewhere that dharma and the like are the fruit.",
        '0.16': "A distant mountain looks huge to those who see it, but when one goes near it, there is fear of snakes and tigers. Those who know this, and know that worldly pleasures are terrible and without substance, worship Rama's beloved daily.",
        '0.17': "Can unfired mud pots, merely dried in the summer sun, be filled with thick juice? What can such rites do for the beast-like man who says \"I am wholly independent\"? His eating, giving and bathing rites merely leak away, leaving only bodily exhaustion.",
        '0.18': "There are two initiations, called the outer and the inner: learn them from the wise and be initiated. Give up long-standing hatreds and keep remembering that Hari is the highest of all, whose feet are worshipped by the kshara and akshara persons (Purushas), free from birth and the like, blissful and all-pervading.",
        '0.19': "For the Lotus-eyed Lord there is nothing to reject and nothing to accept, no just or unjust dharma, no hatred or envy, no mother or father. Like a floating gourd that does not let one sink, he carries across the ocean of worldly life.",
        '0.20': "(The verse breaks off.) Even a dull man, if he gladly wears gopichandana and the sacred marks, and puts garlands of tulasi and lotus seeds around his neck, saying \"Mukunda, Lord of Shri and Bhu, worshipped by the three worlds, master of all, is my family deity\", is protected by him.",
        '0.21': "(The text of this verse is partly unclear.) The verse mocks a man's claim of lordship (prabhutva): in his mother's womb nobody called him lord; and when the body leaves him, the \"lordship\" by which he was called king runs away, though it is shown to be there while he is near.",
        '0.22': "In the one way in which Vasudeva is the Lord, Brahma, Rudra, Shachipati (Indra) and all the gods who are called lords are called his servants. Leaving this good path, the man who practises the \"soham\" (I am He) worship: when bodily and fate-sent troubles come, why does he not free himself from them?",
        '0.23': "In that Supreme Brahman, qualities such as pervading the three worlds, controlling, sustaining, ruling and lordship have no lack; they are his very nature in one form and never leave him at any time, just as servitude never leaves the jivas.",
        '0.24': "Ever new, unchanging, the best of friends, abiding in Pranava, source of the origin of the letters, made of speech and mind, delighting in the Sama chant, he dwells separately in each jiva in the forms of Datta, Kapila and Hayagriva, and moves them according to each one's fitness and karma.",
        '0.25': "The Shrutis are his words and the pure Smritis his instruction; the host of jivas and Prakriti are called his two images (pratime). Remembering that all other actions are worship of Lakshmi's Lord, do not ask for the four human goals even in a dream.",
        '0.26': "As a king pays wages according to service to the messengers who carry his orders and pleases them, so Matarishva's beloved (Hari), with great love, pleases here and hereafter those who hold fast to his good qualities.",
        '0.27': "(The first two lines are unclear.) A lamp noticed in daylight is put out at once; and when Hari is near ... It is not a mere manner of speaking: the sinful deeds of good people become merit, and the meritorious deeds of sinners become sin.",
        '0.28': "Like traders who go about to earn wealth, go to the houses of the learned to hear the scriptures; reflect on them and teach others. Do not keep company with the wicked even in a dream. The Lord grants the desires of those who bow to him, happiness here and hereafter.",
        '0.29': "Delusion about the doer, the action and the object: these three are the causes of much worldly life for the three kinds of jivas. Drive them away at all times, and without falling prey to the three deluders, keep thinking everywhere of the Support of all, without forgetting.",
        '0.30': "If a man who says \"I am independent\" were truly so, why is it that in sleep he keeps silent and does not answer when spoken to, in the waking state acts only when the Lord grants it, and does not avert the four states of consciousness when they come?",
        '0.31': "These are not mere clever words but statements of Shruti and Smriti; on reflection they are steps to liberation. To those who recite each and every word with devotion, the many-formed Lord gives the manifestation of the joy of their own true nature and frees them from the fear of worldly life.",
        '0.32': "(The text of this verse is partly unclear.) A garland made of the jewel-qualities of Srinivasa, strung on the thread of the Vayu (Prana) doctrine, and offered as a garland of words: if it falls under the eyes of the ignorant, it is as unfit as a ruby placed in the hand of a monkey.",
        '0.33': "O Lord whose lotus feet are served by Shri, Brahma, Rudra, Shesha, Indra, Kama, the Sun, the Moon, the guardians of the directions, sages, gandharvas, kinnaras, siddhas and sadhyas! Protector of devotees who rely on your feet, full of compassion, moon to the night-lotus of Lakshmi's heart!",
        '0.34': "Would the discerning refuse to look into a mirror just because someone calls it by a name in a different language? Even if it is in the vernacular, will the wise, who know, fail to hear with the greatest delight what tells of Madhava's qualities?",
        '0.35': "If, seeing the sun's disc, a hostile thief does not bow and rejoice but abuses it, is the sun harmed? If a mocker scorns this as \"not Sanskrit\", what then? The lotus-eyed Lord is always pleased with those who listen with devotion in the first place.",
        '0.36': "Ganga water held in the skull of an outcast is not counted as fit to drink; likewise the bad poems composed by other poets are not worth the wise hearing. But the vernacular verse that carries the story of Kriti's Lord counts as Sanskrit (refined) itself, and gives a good destination to those who hear and tell it with devotion.",
        '0.37': "I have not read or heard the Vedas, the shastras and the reasoned works, and I never had the constant company and talk of saints. By the grace of the followers of Madhva's teaching I spoke what Jagannatha Vithala, Lord of Rama (Lakshmi), made known to me within.",
      },
    },
    'harikathamrutasara-17': {
      summary: "Sandhi 17 (Svagata-svatantrya, Hari's own independence): Supreme Vishnu alone is independent; Lakshmi lives on his chest and Brahma and Vayu are his two ministers. He divided his independence into measured shares for Shiva, Indra, Kama, the sense-deities, the jivas and the demons beginning with Kali, and so gives each the power to act and to enjoy its merit and sin. Within countless beings he works, untouched, like a lotus leaf in a lake. He takes the merit and burns the sin of those who offer their deeds to him. The sandhi closes with its source (the Vishnu-rahasya) and the poet's request for forbearance.",
      verses: {
        '0.0': "By the grace of the guru, I shall tell the nectar-essence of Hari's stories; devoted devotees of the Lord, listen to this with reverence.",
        '0.1': "Supreme Vishnu alone is independent. Lakshmi lives on his chest, and Brahma and Vayu are his two ministers, dear to him in all deeds. The serpent-adorned Shiva presides over the three kinds of ego, and Indra, the Sun and others are called the deities of the senses.",
        '0.2': "Like these denizens of heaven, demons such as Kali act in all bodies on their own. As Brahma presides over the ego, Kali, the lowest, does so for the opposite side; Madhu, Kaitabha, Krodhi, Shambara and others are called lords of the mind.",
        '0.3': "Like the gods, they too act daily in all the senses under such names of their own. And like a king who gives each servant a reward according to service, Hari divided his own natural independence and gave it out.",
        '0.4': "(The figures are partly unclear.) He divided his countless independence into four parts; taking one part he made it tenfold; to Vayu with his five breaths and to four-faced Brahma he gave (shares, five and a quarter units to Brahma); again making it tenfold, he placed two in Sadashiva.",
        '0.5': "(The figures are partly unclear.) He put one and a half in Indra and Kama, one in the deities of the ten senses, one in all other jivas, and four and a half for the hosts of demons beginning with Kali. The last lines, about the shares of Lakshmi and of himself, are unclear.",
        '0.6': "Having divided the principles among gods, humans and demons, Rama's delight, Hari, sports within each of the three kinds. Without altering their karma, he effortlessly gives each of them at the end of the kalpa the destination they have earned.",
        '0.7': "As a lamp flame in a house follows its wicks and looks right to the crowd of people, Hari shows himself everywhere according to each. When from time to time he sports blissfully with his consorts Shri, Bhu and Durga, the deeds of the three gunas arise for the jivas.",
        '0.8': "When the pairs of deeds done through the senses (merit and sin) are offered to him, Govinda takes the merit and reduces the sin to ashes. The Lord of Indira also takes the merit that stands with those who slander his devotees and gives it to his own, and gives the slanderers the sins to eat.",
        '0.9': "(The text of this verse is partly unclear.) To mortals who do not, at the proper times, condemn those who drive others to sinful acts, and who do not praise the qualities and deeds of those better than themselves, he gives all the faults, such as the killing of a cow, a brahmin or a woman. Do not doubt this: it is the view of all the scriptures.",
        '0.10': "The very merciful Lord gives merit and sin to Hiranyagarbha (Brahma) and the others, and to the progeny of demons beginning with Kali, according to their rank, from the portions of independence he has given. Since beings of little power could not enjoy (their fruits) by themselves, he made all of them enjoy.",
        '0.11': "The Lord of true valour, to give merit and sin to all, made forty portions and gave people only a tiny part. Giving them the capacity himself, he always enjoys and makes all jivas enjoy the gross objects.",
        '0.12': "Do darkness and the sun ever exist together in one place? Does a mountain fear wandering, cold or heat? In the same way Lakshmi's Lord, dwelling in countless jivas and doing their activities, remains like a lotus leaf in a lake, unaffected.",
        '0.13': "To Brahma and the other gods, to Kali, Shambara and all the demons, he daily gives merit and sin in shares, as one who knows the capacity of a great pot fills it from the ocean's water: dwelling in them as the original of their reflections (pratibimba), he gives each fruit according to its fitness.",
        '0.14': "This much is from the Vishnu-rahasya, as Bhrigu the sage told it to Indradyumna. Let the wise hear it daily without envy. Where there are improper words, do not count them: so I humbly request the learned.",
        '0.15': "Fearless Lord of the universe, father of Brahma, killer of your uncle, beloved of Madhva, source of all beings, bright as countless suns, great king, saviour of Gautama's wife, refuge of the helpless, greatest of teachers: Jagannatha Vithala protects the devotees who trust him.",
      },
    },
    'harikathamrutasara-18': {
      summary: "Sandhi 18 (Kridavilasa, Hari's sport; Sarva-svatantrya, his complete independence): every act of living beings, from digestion and speech to sleep, is done by Hari dwelling within them for his sport and to give each its destination. He gave out his independence in set portions (Brahma 52 and Vayu 48 of one hundred; Shiva 20, Indra and Kama 15, the gods 10, the jivas 10 and the demons 45 of the other hundred). He takes the merit and burns the sin of those who offer their deeds to him, and gives the merit of those who do not to the gods, as ownerless fruit is carried off. Even one Hari-name on the tongue brings his protection; the sandhi ends by recommending the Bhagavata and offering all the senses to Vayu.",
      verses: {
        '0.0': "By the grace of the guru, I shall tell the nectar-essence of Hari's stories; devoted devotees of the Lord, listen to this with reverence.",
        '0.1': "Digesting, eating, walking, dining, speaking, mating, sleeping, seeing, staying still and moving: can people manage any of these efforts without him? Know that it is the Lord of the pure abode who, by his grace, dwelling within the host of jivas, himself does all these fit and unfit deeds, and praise him.",
        '0.2': "Hari, of great fame, enters the body and constantly does many movements; seeing them, people say \"he is alive\". The lesser ones, seeing this, rejoice and serve the body; the moment he leaves it, they know it for a corpse and neglect it.",
        '0.3': "For his sport and to give each its destination, he gives bodies and plays at will, entering Brahma, Shiva and the rest, and doing many kinds of action also within the foolish demons. He has no loss or gain from it: know this at all times.",
        '0.4': "The Lord praised by the perishable beings, he is the overseer within Brahma, Vayu, Shiva, Indra and the gods and demons, and does the activity in all of them. Imperishable, the true Self, depending on no one else, distinct from all, he protects the world.",
        '0.5': "Dwelling in female form within all women, Shri, Sarasvati, Bharati, Girija, Shachi, Rati, Rohini, Samjna, Shatarupa and the rest, he gives each trust in himself and fulfils their wishes, knowing their fitness.",
        '0.6': "Like boys who play with a stick for a horse, Lakshmi's beloved puts his quality of independence into Brahma and the rest and sports. Without revealing himself, he is ever favourable to his own people and unfavourable to the wicked.",
        '0.7': "The Lord who rides Garuda, called by many forms and names, stays near them and does all their activities. He feeds them merit and sin according to their nature, the benefactor, Supreme Lord, full bliss and mass of knowledge.",
        '0.8': "How can one who toils for worldly things know the great glories of Lakshmi's Lord? Only those who forget worldly pleasures every day, take the meaning in their minds and praise the sense of the scriptures with the greatest zeal, lost in joy, can know them, and no one else.",
        '0.9': "How can knowledge of the giver of bondage and liberation come to the dull-minded? Not knowing that a drop of happiness is like a mountain of sorrow, they seek happiness from other gods. Can one who has abandoned the worship of Mukunda have the joy of liberation?",
        '0.10': "(The end of the verse is cut off.) As a king graciously gives authority to his ministers, assigns work to his own people and dispenses honour and dishonour, Janardana, unconquered within all, has all purposes carried out and does them himself, and so brings them to the fruit.",
        '0.11': "To give his independence to Brahma and the other gods and demons, Vasudeva took half, divided half of that into four, and made one part a hundredfold: fifty-two went to Brahma, forty-eight to Vayu, and half of each to their wives Vani (Sarasvati) and Bharati.",
        '0.12': "Taking another part and dividing it into a hundred, he put twenty in Shiva, fifteen in Indra and Kama, ten among all the gods, ten in the host of jivas, and forty-five in the demons.",
        '0.13': "(The end of the verse is cut off.) Dividing the rest in three, he kept two parts in himself and gave one to Lakshmi. Giving independence to all, he gives his followers their tasks, as a king does, and then makes the three gunas show themselves as he weighs their good and bad.",
        '0.14': "To the blessed who help in good deeds he gives the fruit of the merits of demons like Kali, and the fruit of the gods' sinful deeds he gives to those who do wrong. Such is the ocean of mercy: is there an equal for him who has no comparison?",
        '0.15': "(This continues into the next verse.) The one who says \"there is an equal to the Incomparable\", who is envious of his devotees, who preaches difference between qualities and the one who has them, who hates those wearing the conch, discus and upright mark, and who does not listen to Hari's deeds but listens to worldly gossip...",
        '0.16': "(The end of the verse is cut off.) ...all such malicious wretched jivas are called demons by the wise. Seeing the wise men's knowledge and deeds they revile them, and leaving the God of gods, they live all their lives serving petty people, held in ignorance.",
        '0.17': "(The text of this verse is partly unclear.) Desire, greed, anger, pride, violence, deceit, falsehood, hypocrisy and trickery; seeing difference among the incarnations of the Lord of three abodes; eating tamasic food such as meat offered; and the company of the proud and wealth-blinded: in such company darkness itself increases.",
        '0.18': "The qualities of good people: knowledge, devotion, detachment, humility, hearing the puranas and shastras, reflection, giving, self-control and restraint of the senses, sacrifice, truth, non-violence, compassion for beings, meditation, singing the Lord's names, silence, japa, austerity, vows, bathing at holy waters, mantras, hymns and salutation.",
        '0.19': "Because he has put a small portion of independence into them, qualities and faults show in good and bad jivas. Breathing, eating, drinking, sleeping, play, mating, walking, joy, sorrow, dream, deep sleep and waking happen to the conscious being.",
        '0.20': "(The text of this verse is partly unclear.) Keeping half in himself and dividing the other half, the destroyer of sorrow gave independence as before. Ganga's father, for the growth of the happiness of those to whom he gives, knowing the fitness of those in Brahma, Vayu, Shiva and the others...",
        '0.21': "To one who, not knowing what Krishna does, says out of ego \"apart from me there is no one subject to command or prohibition\", he gives both fruits. Leaving the sinful acts of the demons, he draws out their merit, keeps it in himself, and in due order gives it to devotees.",
        '0.22': "As a tree's shade follows the sun's rays, the qualities and deeds, bad and good, show themselves because the lotus-eyed Lord pervades all. To the experts in reasoning they say constantly: \"Shri's Lord is the best of the best.\"",
        '0.23': "Mahalakshmi, called Prakriti the root cause, dwells in all and sports; when merit and sin are offered to her Lord, they are like water fallen into the ocean of milk and no longer called mere water: the deeds done by jivas are always counted as auspicious.",
        '0.24': "What can the deeds of the three gunas do to Vishnu, full of knowledge, bliss and strength? In this world, does a worm ever eat fire? Can there be fear of these sins for the one who swallows this egg of Brahma, with Brahma, Shiva and the gods and demons, in the fire of time?",
        '0.25': "(The text of this verse is partly unclear.) The Shrutis, beginning with the Taittiriya passage, say that Moda is the right wing and Pramoda the left (north) wing. As he gives the special happiness of this world (moda) and of the next (pramoda), the blissful Hari is called Moda and Pramoda.",
        '0.26': "Does the ocean ever grow from the rain water of all the earth? Does it become empty when rain does not come? For the Lord who has no lack, who is full in his own bliss, what can the fruits of acts and of non-acts do when they come to him?",
        '0.27': "In the tree of the body there are two birds, ever together in great friendship: the jiva-bird who eats the fruits of karma, and Sri Hari, who partakes of the essence. To the hostile demon hosts such as Kali he gives their special share of sin, and a trace of sin to all.",
        '0.28': "As darkness flees at the sight of the sun's rays, sin is destroyed by the mere look of Lakshmi's Lord; the heap of sin that is in Brahma and all the gods Hari himself reduces to ash, as Agni, the mouth of the immortals, would.",
        '0.29': "(The text of this verse is partly unclear.) Of the four hundred portions, from a tenth he gives other jivas a small part; he gives the gods and demons their special pain and pleasure; and knowing their fitness he gives creatures without intellect, such as ants and mosquitoes, the happiness of the oblation and the pain of death.",
        '0.30': "(The text of this verse is partly unclear.) Kali with his servants falls into the eternal hell, the pit called Andhatamas. But those who worship Hari's lotus feet with devotion, the Brahma of Satyaloka together with the principle-gods, attain their own liberation, the world from which there is no return.",
        '0.31': "If, without forgetting both what is commanded and what is forbidden, one offers it at the feet of Hari, he gives the merit to the children of Aditi (the gods) and the sin to the demons. If one does not give it to the bearer of the discus, the demons come and carry off the merit, like the fruit of ownerless trees, always.",
        '0.32': "As a lamp throws away the sesame dregs, takes the clear oil and breaks the darkness that fills the house, the Lord daily takes the fruit of the merit performed by Kali and all the demon-born, gives it to Brahma and the others, and sports within them.",
        '0.33': "(The verse begins in mid-sentence.) One who eats clean and unclean things daily is still called pure and spotless in the world, in the Vedas and Smritis; and when the wise offer, deliberately and with faith, even an act that is forbidden, he accepts it and uplifts them.",
        '0.34': "(The end of the verse is garbled.) Does anyone beat down and eat forest fruit that has an owner? Fearing that they will be beaten and thrown away if seen, people are afraid even to look. In the same way the deeds one does unceasingly, one's house, wife, children and kin...",
        '0.35': "Whatever deeds you do with the senses of knowledge and of action, keep offering them to Lakshmi's Lord at all times. Once the Lord of life accepts them, he does not send one to various births; if you do not give them to him, the demons carry off all your heaps of merit.",
        '0.36': "A man who knows the meaning of the Shruti and Smriti but is marked by the idea \"I do it\" is not accepted by the Lord when he performs a deed, and instead he gives sins. But for one who says \"Hari is the lord of the fourteen worlds, the controller, grateful for sacrifices\", there is no fault of lost mind, error or distress.",
        '0.37': "(The verse breaks off.) Brahma and the others are only bearers of his command. Knowing that Rama's Lord is the wholly independent one, and offering the fruits of wanted and unwanted deeds to him, who enjoys the essence, he accepts them. The fruit of sin he gives to the demons called Kubera...",
        '0.38': "(One phrase is unclear.) Because he himself, dwelling in the cruel demons, drives them, Hari is called Kubera (the one with a bad body). They call him Surya because the wise reach him, Shukla because he is far from grief, and Akaya (bodiless) because he has no subtle body.",
        '0.39': "For the one who thinks \"great sins that cannot even be told must be destroyed root and branch in a single moment\", if he has just one name of Hari on his tongue, the supremely merciful Krishna takes his hand, places him in his own abode, and gladdens him day after day.",
        '0.40': "As a patient becomes healthy through medicine and diet, so listen well to the Shrimad Bhagavata, cast off the disease called worldly life, and dedicate the ten senses and all objects such as sound to Vayu. Then Sri Guru Jagannatha Vithala will be pleased.",
      },
    },
    'harikathamrutasara-19': {
      summary: "Sandhi 19 (Karma-vimochana, release from the bonds of action): the original Narayana dwells as the cause and the inner Self in everything, sports in his forms, and himself has all deeds done and their fruits eaten, while remaining untouched. One who knows this, acts without desire and offers every deed to Hari is not stained by merit or sin, and Hari protects him without counting his faults. Rites, books and austerities without devotion do not save, any more than a frog carries one across the sea; ask Hari only for devotion, not for small pleasures. He is near the wise and far from the wicked, and answers the call of the devotee as a cow answers its calf, as he accepted Shabari's fruit and Sudama's offering.",
      verses: {
        '0.0': "By the grace of the guru, I shall tell the nectar-essence of Hari's stories; devoted devotees of the Lord, listen to this with reverence.",
        '0.1': "(The text of this verse is partly unclear.) The original Narayana, delighted with Maya (Lakshmi), sports in countless avatars; he is Jayaramana (Lakshmi's Lord), the indwelling power; as Pradyumna among the host of countless conscious beings, and as Aniruddha, lord of peace, he stays inside and outside the abode of the Brahma-egg.",
        '0.2': "In five causal forms and twenty-five forms called effects, thirty forms in all, he sports in this moving and unmoving world, himself free of difference. Cause of the creation of the three worlds, giver of liberation, the omniscient Lord keeps all in his own belly and comforts them.",
        '0.3': "(The text of this verse is partly unclear.) Within effect, cause and doer, together with his consorts, Kapilacharya sports; he himself is moved by none. By his own valour he protects the gods, and punishes the demon host, day after day, while Lakshmi, Brahma and Shiva look on with honour.",
        '0.4': "The pervading Lord, inner Self of his avatars, abides within all this world and in its space. Imperishable, he becomes the space within the world itself; he dwells in the heart-space of the lords of yogis, keeps all within himself and protects them.",
        '0.5': "As fire stays separate in wood and stone, so within cause and effect, called the cause and the effect, he acts in all without showing himself, gives each the fruits that suit its fitness, and comforts them: the ocean of mercy.",
        '0.6': "The pure Lord does, causes and feeds the fruits of action and non-action, good and bad, that rise like waves; free of \"mine\", without ailment, needing no support, knower of dharma, righteous: the evil-minded do not like him, the incomparable wrestler, Shri's husband.",
        '0.7': "As the undersea fires drink the ocean's water, the clouds pour rain and give the earth peace, and fire itself eats the offerings, so Lakshmi's omnipresent Lord himself eats and makes all jivas eat the good and bad fruits of the deeds born of the gunas. Know it so.",
        '0.8': "What use is looking over books, reciting mantras and hymns, or doing japa and austerity from sunrise to sunset, for the one who does not know that the Supreme Self in the heart, free of desire, dwells in all states and does and has all done in everyone?",
        '0.9': "A liquor pot washed daily in the heavenly river: will it ever become pure? In the same way, for the base jivas who do not worship Hari's lotus feet with understanding, all their apparently favourable deeds and the prosperity they bring give only sorrow.",
        '0.10': "With devotion praise without ceasing the surpassing glories of the Controller of the liberated and the unliberated, never forgetting. Without becoming attached to worldly talk and distractions, keep doing the acts ordained by Shruti and Smriti, knowing it is Hari's command.",
        '0.11': "Even if the deed has some lapse, the two kinds of karma-born merit and sin will not stain you if you act without desire. Garuda's Lord, not counting your great offences, gives heaven and liberation and protects you, ever dense with bliss.",
        '0.12': "Self-delighting, full of bliss, easy to reach, supporter of the universe, griefless, whose feet gods and demons worship, fair of limb, bearer of the Sharnga bow, refuge, conqueror of anger, supremely beautiful, higher than the highest, wish-cow of those who surrender, eternal, merciful, lotus-eyed: when called on \"protect us\", the ever-perfect Lord shines forth.",
        '0.13': "Be pure yourself, and offer both prescribed and other deeds without ceasing to the Lord called Sudharma, and so become free of stain. The father of golden-wombed Brahma, out of kindness, does not give you to the evil-minded; he keeps you in his own palace and guards you always in his grace.",
        '0.14': "In every kalpa the wish-tree of those who surrender gives them, according to his own resolve, the fruits they want and do not want. Never worship the Lord who lies on the serpent for small pleasures: he shapes you as a sculptor shapes a stone that falls into his hands, and protects you.",
        '0.15': "Like space, which differs by place, Vasudeva dwells in all beings and is called the Self of the moving and unmoving. In bodies there is no hatred, affection or indifference in him: the Supreme Brahman gives fruit according to each one's way of worship.",
        '0.16': "(The text of this verse is partly unclear.) By worshipping the father of Brahma, troubles do not stay like lightning but are destroyed in due order. He does not like those who deceive; Shrivatsa-marked on his chest, he loves the poor, and as Lord of men he shines like lightning in the sky of the heart.",
        '0.17': "People tell the unlearned that purity of time, substances and rites will uproot all sins at all times; the foolish, instead of praising his feet constantly, in an unbroken stream like a stream of oil, say that rites and the like are what carry one across.",
        '0.18': "Brahma, Shiva, Indra and all the gods cannot reach the limit of his unsurpassable glories by mind or speech. Tired, they take shelter in the shade of the wish-tree of his lotus feet and pray with great devotion: \"Lakshmi's Lord, comfort us.\"",
        '0.19': "(The author's view.) Thinking that water creatures like frogs can carry one across, like the man who says he will cross the ocean on a frog's back, those without knowledge of taratamya (the graded order of beings) cannot know the Lord whom the wise reach; they follow the Saura and Shaiva teachings and are ruined.",
        '0.20': "Like a king's son holding out his hand for a farthing, or like wanting cow dung while the wish-cow is in the house, do not ask the flute-loving Lord for worldly pleasures. Ask for devotion at the feet of Lakshmi's beloved, and praise him.",
        '0.21': "(The text of this verse is partly unclear.) Like a man who went out of hunger into the forest for jujube fruits, fell into a thicket and stood open-mouthed, do not wear yourself out in worldly life serving people who only display the marks of holy men, for your belly's sake, instead of worshipping the father of Brahma.",
        '0.22': "Under the names knowledge, the knowable and the knower, he dwells in the seat of the intellect and the rest, called by those names; showing himself in the sun's orb, he becomes dependent on the devotion of sages such as Shuka and Shaunaka, the moon in the heart-sky of great sages.",
        '0.23': "(The text of this verse is garbled.) The clear part is the instruction: do the service of Hari every day, without worrying about the rules and prohibitions of time and the like; the Lord who loves his devotees places them in his own house and protects them.",
        '0.24': "(The first lines are unclear.) Just as one gives up certain observances when the Shivaratri vow, Dvadashi, Dashami and ancestral rites come together on one occasion, never look at wealth that comes from the despicable; and worship everywhere Hari who dwells within Shri Anandatirtha (Madhva).",
        '0.25': "Lord of Shri, mountain-like, abode on the three peaks, of good auspicious qualities, limitless, of holy name, uplifter of the gods, Raghurama: to those who lovingly praise his great glories every day he gives all they want, as he was pleased with Sudama.",
        '0.26': "Like a child who does not know the marks of his parents, in a foreign land, seeing people like himself, and searching for his own mother and father with the thought \"these look like those who begot me: let me see whether they are\", the wise search (continued in the next verse).",
        '0.27': "In the host of Puranas and the Mahabharata, in each and every word, the wise search with great joy for the qualities and forms of the Unconquered Lord, and every day, with eager delight, they move ceaselessly in the ocean of speech like fish.",
        '0.28': "\"Father of Kama, Hari, Shrivatsa-marked, loving to your own devotees, fair-limbed, dweller in Vaikuntha, giver of conscious bliss, protect us\": at this call he comes with the greatest joy to the envy-free, as a cow answers its calf's cry.",
        '0.29': "He is near to the wise and ever far, farther, hard to reach for the evildoers and the progeny of demons. For those who remember him again and again, he is Garuda, the enemy of serpents, to the great serpent called worldly life, and gives constant happiness to good people.",
        '0.30': "Bearer of discus, conch, mace and lotus, hard to cross and hard to reach, whose lotus feet Brahma, Shiva, Indra, Surya and the other gods worship, undaunted: he spoiled the horse-sacrifice of Shukra's disciple (Bali) and, striding across the egg of Brahma, gave birth to the Ganga: he is called Trivikrama.",
        '0.31': "Among the host of gods other than Hari there is none who is called capable of that; he alone is the highest of all. So at all times, with devotion, giving up all other attachments, be fully absorbed in drinking the nectar of Hari's stories.",
        '0.32': "Giver of the wishes of those who bow, wish-gem of devotees, adorned with jewelled ornaments, beyond the three gunas, profound, of true glory, not counting the faults of devotees, the husband of Earth's daughter, the refuge: the Supreme Self accepted Shabari's fruit when she offered it saying \"Ramarpana\".",
        '0.33': "No one claims \"I know him fully\", no one says \"I reject him\"; there is no place in the world where he is not, and no one who knows him wholly. Like jaggery in a doll-shaped mould, the Lord of Shri and Bhu is within all; he has no equal, the incomparable wrestler of the whole world.",
        '0.34': "(The text of this verse is partly unclear.) Beyond the reach of words, brother of the moon-born, moon of the ocean of the Yadu line, incomparable and limitless: to the devotee who has gained peace and calm he has his prarabdha karma (the deeds already begun to bear fruit) worked out and, merciful, does not leave him, like a fire once kindled.",
        '0.35': "Praised by Shri, Brahma and the other gods, the unborn Lord incarnated on this earth in the womb of Devaki like a man; younger brother of Revati's husband (Balarama), he protected those who took refuge at his feet and destroyed the hosts of demons: Jagannatha Vithala.",
      },
    },
    'harikathamrutasara-20': {
      summary: "Sandhi 20 (Guna-taratamya, the graded order of beings by their qualities): Hari is supreme; Lakshmi comes next, then the pair Brahma and Vayu, then their wives Sarasvati and Bharati, then Garuda, Shesha and Shiva, and so on down through the gods, sages, kings and humans, each step measured in degrees of quality. Jivas are also classed by the three gunas, with Kali the lowest of all. Knowing this taratamya (graded order) is called the door to liberation, a boat across the ocean of worldly life and a staircase to Vaikuntha, to be told to those fit for it. The sandhi closes with a litany of homage to all these beings in order.",
      verses: {
        '0.0': "By the grace of the guru, I shall tell the nectar-essence of Hari's stories; devoted devotees of the Lord, listen to this with reverence.",
        '0.1': "Husband of Shri and Durga, whose lotus feet Brahma and the host of gods worship, pervading the universe inside and outside, bearer of the earth, with Shesha as his umbrella, free from every prohibition, wonderful in deeds, full of knowledge, body of bliss, supremely pure and of fine conduct.",
        '0.2': "Eternal, spotless, known by the Vedas, far from the changes of creation, sustenance and dissolution, worthy of praise and worship, renowned, served by the liberated and the unliberated, of true will, refuge, everlasting, loving to your servants, remover of fear, dearest of all, Jagannatha: protect me!",
        '0.3': "(The text of this verse is partly unclear.) Rama (Lakshmi) follows the form and qualities of the Supreme Person and appears in an unbroken stream, incomparable, called free of sorrow and full of bliss; for Hari she becomes a threefold abode, ornaments, clothing and weapons; and called Akshara, she destroys the enemies.",
        '0.4': "Compared with him, young Shri is said to be less in infinite qualities. Eternally liberated, changeless, beyond the three gunas, Mahalakshmi, mother of Brahma and Vayu, whose sins are washed away, is renowned always in the Shrutis and Puranas.",
        '0.5': "Brahma and Vayu are a pair, equal in rank, called Parabrahma by Rudra and the other gods. Mahalakshmi is higher than the twins by crores of qualities of their own kind, so Brahma and Vayu are called lower by countless degrees.",
        '0.6': "(The last lines are unclear.) Their wives Sarasvati and Bharati are lower than their husbands by a hundred qualities, in knowledge, strength and the rest. Vagdevi (Sarasvati) excels; because of their positions, the wise should meditate with devotion on the Lord in Brahma and Vayu.",
        '0.7': "(The text of this verse is partly unclear.) Garuda, Shesha and Shiva are equal to each other and a hundred qualities below Vani (Sarasvati); of the three, the one who holds the position of Shesha is the greatest. Parvati, daughter of Mena, is two qualities above Varuni and Sauparni.",
        '0.8': "(The text of this verse is partly unclear.) Sauparni, Varuni and Parvati, the wives of Garuda, Shesha and Mahesha, are ten qualities lower than... (their husbands); Indra and Kama are ten qualities lower than Gauri, Hara's wife; Manmatha (Kama) is lower than Indra by position.",
        '0.9': "(The text of this verse is garbled.) It continues the graded list downward by tens and fives of qualities, naming Ahamkarika Prana, Kama's associates, Aniruddha (of the ego), Rati, Manu, Daksha, Guru (Brihaspati), Shachi, and Pravaha.",
        '0.10': "(The text of this verse is partly unclear.) Lower than Pravaha by two qualities are the Sun, the Moon, Yama, and Svayambhuva Manu with his wife Shatarupa, the four of them; below them by a quarter and half-quarter of a quality come Narada, Bhrigu, Agni and Prasuti.",
        '0.11': "(The text of this verse is partly unclear.) It goes on down the graded list: below Agni by two qualities come Brahma's sons such as Marichi; Vaivasvata (Manu) and Vishvamitra are lower by a small degree; then Nirriti, Tara and others, and Kubera and Vishvaksena, each slightly lower.",
        '0.12': "(The text of this verse is partly unclear.) Kubera, Vishvaksena and Gauri's sons are equal to the others named; and groups of gods such as the Adityas, the forty-seven Maruts, the Vasus, the Rudras, the Vishvedevas, the two Ashvins, the Pitrs and the Earth are listed at the same level.",
        '0.13': "Lower than these are Chyavana, Sanaka and the other sages, Kavi, Jayanta, Kashyapa, the eleven Manus; Dhruva, Nahusha, Shashibindu, Haihaya, Dushyanta; Bali son of Virochana and the other seven Indras; Kakutstha, Gaya.",
        '0.14': "Prithu, Bharata, Mandhata, Priyavrata, Marutta, Prahlada, Parikshit, Harishchandra, Ambarisha, Uttanapada and the others, a hundred in all, are of holy fame and have the Lord with the mace as their support. They are lower than Priyavrata by two qualities and are called gods born of karma.",
        '0.15': "(The text of this verse is partly unclear.) Lower still are Nalini, Samjna, Rohini, Shyamala, Virat and Parjanya; the wife of the Wind's friend (Agni) is two qualities lower; then Ganga and Budha (Mercury) two qualities lower; then Usha and Shanaishchara (Saturn), each lower again.",
        '0.16': "(The text of this verse is partly unclear.) Pushkara is lower by two qualities as lord of rites; the Ajanaja gods and the long-lived Pitrs are higher than the servants and Pushkara; the best of the singers of Indra's court, Tumburu and others, are lower by ten qualities; nine crore sages are equal to Tumburu, with a hundred of them excepted.",
        '0.17': "(The text of this verse is partly unclear.) Their wives and the young apsaras are equal to them, the best excepted; human gandharvas are lower by twelve qualities; kings of the earth by ten; women are a hundred qualities lower than the best of men.",
        '0.18': "(The text of this verse is partly unclear.) By the three gunas jivas fall into nine classes. The sattva-types are the three highest classes; those who rank as rajas-sattva are called devotees of the Lord. The eternally bound, the rajas-rajas, are born on earth, in heaven and in hell and move about on earth; then come the rajas-tamas.",
        '0.19': "(The end of the verse is cut off.) Then the tamas-sattvic, the countless named hosts of asuras, are called the tamas-rajasic, the multitude of daityas. The tamas-tamasic are Kali and his wife; among the lowest, the basest and evil-souled is called Kali.",
        '0.20': "There is no sinful jiva like him in all three worlds, for he is called the mine of nine kinds of hatred. Through war, gold, dancing girls, young women, gambling, drink and lies he blinds people with delusion and ruins them: knowing this, give these up.",
        '0.21': "(The text of this verse is partly unclear.) Having created the series of the three kinds of jivas, the compassionate Lord sports with his consorts. Great souls who know the detailed gradation of gods and demons he is pleased with and lifts out of worldly life.",
        '0.22': "For followers of the doctrine of Madhva (Vayu's son), knowing the graded order of gods and demons is absolutely necessary, at all times. It is a forest fire to the forest of sin, a new boat to cross the ocean of worldly life, a staircase to the world of Vaikuntha: so it is called.",
        '0.23': "The knowledge of taratamya is the door to liberation for devotees: the wise should teach it and revel in the ocean of bliss. To cruel people it is harsh in the ear. Tell it daily to those who are fit, leaving aside the wrong reasoners.",
        '0.24': "(A litany of names begins here and continues in the next two verses.) Hari, Shri, Brahma, Vayu, Bharati, Garuda, Shesha, the six queens, Girija, Indra, Kama, Prana and Aniruddha, Shachi, Guru, Rati, Manu, Daksha, Pravaha-Marut, Manavi, Yama, the Moon, the Sun, Varuna, Narada, Agni, Prasuti, the sage Bhrigu...",
        '0.25': "...Brahma's sons such as Marichi, Vaivasvata, Tara and Mitra, Nirriti, the wife of Pravaha-Marut, Kubera, the Ashvins, the lord of the gods (Vishvaksena), Shesha, the hundred, the Manus, Uchitthya (Chitthya), Chyavana and the other sages: to all these I bow.",
        '0.26': "I bow to the hundred kings of holy fame. To Bhagirathi (Ganga), Virat, Parjanya, Rohini, Shyamala, Samjna, Agni's wife, Budha, Usha, Kshiti (Earth), Shanaishchara and Pushkara I bow and pray: let them give me devotion and knowledge.",
        '0.27': "Krishna's sixteen thousand one hundred wives, the great sages beginning with Agastya, the apsaras beginning with Urvashi and the hundred Tumburus: may they make me sing the glories of Kamsari (Krishna).",
        '0.28': "Serve daily with joy and in every way the pure ones, the gods named Shuchi and Shuddha, the Ajanaja gods, the long-lived Pitr-gods, the human gandharvas, the kings and the best of men, knowing that they stand among the line of Vaishnavas (devotees of Vishnu) on this earth.",
        '0.29': "For devotees who think in order of the hundred grades of excellence, from the best of humans up to four-faced Brahma, Shri's treasure, Jagannatha Vithala, himself gladly gives the four human goals. Let the wise recite this lovingly and never forget it.",
      },
    },
    'harikathamrutasara-21': {
      summary: "Sandhi 21 (Brihat-taratamya, the extended graded order): a long catalogue that names the incarnations of Hari, then ranks Lakshmi, Brahma and Vayu, their wives, and every class of gods, sages, kings and gandharvas below them, with the figures from the epics and Puranas in whom each is said to have appeared on earth or entered another's body. The order is stated in degrees of quality, and the text warns that it should not be taken as contradicting the scriptures. Those who know it and recite it daily are given the human goals by Jagannatha Vithala, who shows himself in their hearts. Many verses are lists of names and their text is partly garbled; the translations give only what the text clearly says.",
      verses: {
        '0.0': "By the grace of the guru, I shall tell the nectar-essence of Hari's stories; devoted devotees of the Lord, listen to this with reverence.",
        '0.1': "The Lord's incarnations and forms are named: Fish, Tortoise, Boar, Narasimha, the dwarf (Vamana), Parashurama, Rama son of Dasharatha, Krishna of the Yadavas, Buddha, Kalki, Kapila, Vaikuntha, Srinivasa, Vyasa, Rishabha, Hayagriva, Narayana, Hamsa, Aniruddha, Trivikrama, Shridhara and Hrishikesha.",
        '0.2': "He is called Hari, Narayana, Krishna, destroyer of the clans of the gods' enemies, bright as the sun, faultless and full of bliss; the best of all gods, all-pervading, supreme and ancient Person, free of old age and death, Vasudeva, the Self of countless forms.",
        '0.3': "Lakshmi, mother of Brahma, is always full of knowledge, strength, devotion and the other qualities, yet by the strength of Hari's grace she is called lower than him in infinite qualities. Among the liberated and unliberated gods there is no one equal to the Ancient Person or to Prakriti (Lakshmi).",
        '0.4': "Names of Lakshmi: Shri, presiding over the three gunas; Kumbhini (Earth), Mahadurga, Ambhrani, Rukmini, Satya, Shanti, Kriti, Jaya, Maya, Mahalakshmi, Janakaja (Sita), Kamalalaya, Dakshina, Padma, Trilokeshvari. Dwelling in the atom and in the great, she is called without comparison.",
        '0.5': "Compared with the wife of the Horse-faced Lord (Lakshmi), golden-wombed Brahma and Vayu are lower by crores of qualities at all times. Not at the level of Garuda, Shesha or Indra but far above them, by the gracious glance of Shri's Lord they act in all beings.",
        '0.6': "(The text of this verse is garbled.) It lists names of Brahma and Mukhya-prana (Vayu), among them Purusha, Brahma, Virinchi, Mahan, Marut, Mukhyaprana, Dhriti, Smriti, Vibhishana, Vishvacheshtaka (mover of all), Veetabhaya (fearless) and Bhima.",
        '0.7': "(The text of this verse is partly unclear.) The list of names of Vayu and Brahma continues: Anila, Sthiti, treasure of detachment, Rochana, Dashamati, Animisha, the pure sattva-bodied one, atomic and great in form, Amrita, Hanuman and the other avatars, and the one who has reached the position of Padmasana (Brahma).",
        '0.8': "Matarishva (Vayu) and Brahma are said to be subordinate to and lower than the Mother of the world (Lakshmi). Shri's Lord, always present in both through their surpassing devotion, knowledge, strength and form, pervades the sentient and insentient through them under their several names.",
        '0.9': "(The text of this verse is partly unclear.) Names of Sarasvati: Vedatmika, Brahmi, full of supreme bliss and strength, Shraddha, Priti, Gayatri, mother of Garuda and Shesha, Vani; controller of the senses, honoured in the fourteen worlds.",
        '0.10': "(The text of this verse is partly unclear.) Names or forms of Bharati: Draupadi, Panchali, Kashija and others. The wives of Brahma and Vayu are said to be lower by fifty-one qualities; then the verse begins on the incarnations of Rudra and the persons entered by Hari and Vayu.",
        '0.11': "(Names only; some unclear.) Persons entered by Hari and Vayu: Nara (Arjuna); Lakshmana, with the entry of Sankarshana; Balarama, with the entry of the white-haired form of the Supreme Person. Then the avatars and entries of Rudra: Hara, Sadashiva, Shuka, Jayagishavya, Aurva, Drauni (Ashvatthama), Vyadha and Durvasa.",
        '0.12': "Garuda, Shesha and Shiva are equal among themselves; they are a hundred qualities lower than Bharati and Brahma's wife. Jambavati, Hari's wife, always carries the entry of Shri; five (queens) are five qualities lower than Garuda and Shesha.",
        '0.13': "Nila, Bhadra, Mitravinda, Kalindi and Lakshmana (queens of Krishna) are named; lower than these maidens are Varuni, Sauparni and Girija (Parvati). Revati carries Lakshmi's entry. Shailaja (Parvati) and the others are ten qualities lower than their husbands.",
        '0.14': "(Names only; the text is partly unclear.) Forms of Indra and others: Nara (Arjuna), with the entry of Narahari; Purandara, Gadhi, Kusha, Mandaradyumna, Vikukshi and Vali, avatars of Indra; Bharata, entered by Brahma; Samba, Sudarshana and Pradyumna; Sanatkumara among Sanaka and the others; Shanmukha (Kartikeya) and Kama.",
        '0.15': "Indra and Kama are ten qualities lower than Parvati and Varuni; the presiding deity of the body, Prana, is ten qualities below Indra. Rati (Kama's wife), Daksha, Guru (Brihaspati), Shachi (Indra's wife) and Svayambhuva Manu are said to be six who are equal to one another and ten qualities lower than Prana.",
        '0.16': "(The text of this verse is partly unclear.) Aniruddha, Kama's son, is named along with Shatrughna, the younger brother of Sita's Rama, and Aniruddha, grandson of Balarama's younger brother. Kama's wife is called Rukmavati and Lakshana; and Paulomi (Shachi) has the names Chitrangada and Tara.",
        '0.17': "In the Treta age the one named Tara worshipped Sita's Lord (Rama); Uddhava, joined with Vayu, became dear to Krishna; and Drona, joined with Brahma: these three on earth are said in the Mahabharata-tatparya to be incarnations of Brihaspati.",
        '0.18': "Pravaha is five qualities lower than Manu and his peers; the Sun, the Moon, Dharma (Yama) and Manavi are two qualities lower than Pravaha. Saints should think every day, at all times, of the forms of the Sun, the Moon and Yama-Dharma.",
        '0.19': "Yudhishthira (Dharmaja), who carries the entry of Vayu, the bear (Jambavan), Vidura and Satyajit are four forms of Dharma. Sugriva, entered by Brahma, and Karna, entered by a form of Hari, are the Sun's two avatars. The Moon is Angada, who carries the entry of Indra.",
        '0.20': "Varuna is lower by a quarter and half a quarter. Mahabhishak, Dardura, Sushena and Shantanu are four forms of Varuna. The divine sage Narada is slightly lower than Varuna; Agni, Bhrigu and Prasuti, wife of the goat-headed Daksha, the three, are lower than Narada.",
        '0.21': "Nila, Dhrishtadyumna and Lava are forms of Agni. Bhrigu, because he kicked Hari, became the hunter (Vyadha). These three are higher than the seven sages and lower than Narada, the crest of sages. Prahlada, joined with Vayu, became King Bahlika.",
        '0.22': "Among the karma-born kings, Prahlada, by the strength of the sage Narada's grace, is counted equal to Agni, Bhrigu and Daksha's wife. Vaivasvata Manu and Gadhi's son (Vishvamitra), the two, are slightly lower than Agni and always equal to the seven sages.",
        '0.23': "(Partly unclear.) Brahma's sons, the self-controlled sages Marichi, Atri, Angiras, the wise Pulaha, Kratu, Vasishtha and Pulastya, are lower than the husband of Svaha (Agni). The Sun named Mitra is Bhishmaka, joined with Rahu; a twin form was known by the name Tara in the Treta age.",
        '0.24': "(A list of names, partly unclear.) Durmukha and Ghatotkacha, joined with Hara; Pravahi and Tara, the wife of Guru (Brihaspati), are equals and higher than Parjanya. King Bhagadatta, joined with the dark-throated Shiva, and Katthana are two forms of Kubera; Ganesha is Charudeshna; the Ashvins are equal.",
        '0.25': "The eight Vasus are Drona, Dhruva, Dosha, Arka, Agni, Prana, Dyu and Vibhavasu. Agni (Krishanu) is the foremost; the Vasu named Dyu is the noble Bhishma; the Vasu named Drona, joined with Brahma, is Nandagopa. Leaving out Agni, the chief, the other seven are equal to one another in knowledge and the other qualities.",
        '0.26': "Bhima, Raivata, Oja, Ajaikapat, Mahan, Bahurupaka, Bhava, Vama, Ugra, Vrishakapi and Ahirbudhnya: among these great ones (the Rudras), Uma's beloved (Shiva) is the best; the other ten are always equal among themselves.",
        '0.27': "(Names only; the text is partly unclear.) Bhurishrava is joined with several of the Rudras, such as Ajaikapat and Ahirbudhnya; Shala is the one named Virupaksha; the wise Kripa is Vishkambha; Sahadeva and Somadatta are also named, and Patratapaka, who took two forms on earth.",
        '0.28': "(A list of names, partly unclear.) The Adityas: Mitra, Varuna, Parjanya, Bhaga, Pusha, Vivasvan, Savitri, Dhata, Aryaman and Tvashtri. Savitri dwells in Devaki's son; Bhanu is called the son of Vibhavasu; and Virasena is the one named Tvashtri.",
        '0.29': "Among the twelve Suns six are the best: Vivasvan, Varuna, Shakra, Urukrama, Parjanya and Mitra. Pandu, who carries the entry of Marut, is the one called Paravaha; Kesari, king of beasts, Sampati and Shveta, the three, are portions of the Maruts.",
        '0.30': "(A list of names, partly unclear.) Portions of Prana: Pratibha, Chekitana, Viprithu, Saumya, Maruta, Vitata, Sarvottunga and Gaja. The second, Apana: Gavaksha and Gavaya. The third, Vyana. Udana: Vrishaparva and Sharvatrata. Samana: Gandhamadana.",
        '0.31': "(Partly unclear.) Among the five (lesser breaths), Kuntibhoja is the one named first; Naga, Krikala, Devadatta and Dhananjaya have no avatars. Avaha, Udvaha, Vivaha, Samvaha and the Marut who is Pravahi's lord: all the Marut hosts are always slightly lower than Pravaha.",
        '0.32': "(The verse is incomplete.) The Maruts are said to be lower than the ten Vishvedevas. Five of these became the sons of the noble Draupadi; some are called Kaikeyas on earth, at all times.",
        '0.33': "Prativindhya, Shrutasoma, Shrutakirti, Shatanika and Shrutakarma are Draupadi's sons. They are joined with the five peerless Gandharvas, Abhitamra the chief, Chitraratha, Gopa, Kishora and Bala, and they are called the sons of Dharma, Vrikodara (Bhima) and the others.",
        '0.34': "(Partly unclear.) Vivida and Mainda, Nakula and Sahadeva, are the Ashvins, and Indra's entry is always in them. Heaven-and-Earth, the Ribhu, Vishvaksena the son of Vayu, Uma's son Ganesha, Kubera and others are called slightly lower than Mitra.",
        '0.35': "The sons of Fire called Chyavana and the sage Uchathya; the Manus Chakshusha, Raivata, Svarochisha and Uttama; the Savarnis named Brahma, Rudra, Indra, Deva, Dharma and Daksha; and Shashibindu, Prithu, Priyavrata, Mandhata, Gaya, Kakutstha and Dushyanta's son (Bharata).",
        '0.36': "In Bharata, born of Rishabha, born of a doe and born as the brahmin Bharata, and in all the other kings, the entry of Shri Vishnu and Prana abides every day. Divaspati, Shambhu, Adbhuta, Bali, Vidhrita, Ritadhama and others are named, and the eight Gandharvas. (Partly unclear.)",
        '0.37': "The karma-born who are called kings are a hundred qualities lower than Vaishvanara (Agni); Bali and the chief Pavakas (fire-gods) are slightly lower than Ganesha. Sharabha is the cloud-lord named Parjanya; Samjna is the Sun's wife; Rohini is the Moon's wife; Shyamala is Devaki (continued in the next verse).",
        '0.38': "(Partly unclear.) ...and she is called the queen of Dharmaraja (Yama). Varuna's wife, Usha and the others, six in all, are two qualities lower than the Pavakas. Svaha is lower than two or three of these; and Usha-devi, the Ashvins' wife, is ten qualities lower than the wife of Vaishvanara.",
        '0.39': "(Partly unclear.) Budha (Mercury), joined with Sudarshana, Indra and other gods, is the one called Abhimanyu. The Ashvins' wife is lower than Budha (Shalya and the Magadha are also named). Shanaishchara (Saturn) is lower than Usha-devi, and Pushkara, lord of karma, is lower than Shani: so say the wise.",
        '0.40': "(Gandharvas who took forms on earth; partly unclear.) Viradha, and secondly Sanjaya, joined with the Marut Udvaha, are Tumburu. The learned Janamejaya is Chitraratha, joined with Tvashtri. Damaghosha and Kabandha, the two, are the Gandharva Danu. Akrura, joined with Manu and Brahma, is the one called Kishora.",
        '0.41': "(Partly unclear.) King Dhritarashtra, joined with Vayu, is Dhritarashtra the singer of the gods. The crocodile and King Drupada are the Gandharva Huhu, joined with the Marut Avaha. King Virata is Haha, joined with Vivaha. The python is a Vidyadhara; and Ugrasena is the one named Ugrasena.",
        '0.42': "(Partly unclear.) Yudhamanyu and Uttamaujas are Vishvavasu, joined with Brahma; the one joined with the Sun-gods Mitra and Aryaman is called Paravasu; Satyajit on earth, joined with Mitra, is Chitrasena. They are always called the singers of the gods who feed on nectar.",
        '0.43': "All the remaining Gandharvas, beginning with Bali, are called cowherds on earth. Sairandhri is the apsara Pingala; Tilottama was formerly Nakula's wife, called Parvati; all the gopis of Gokula, Shabari and others are apsaras.",
        '0.44': "Among the sons of Agni, who became sixteen thousand one hundred women, Mother Rama (Lakshmi) entered and dwells in Krishna's queens under those names and forms. Kasheru, daughter of Tvashtri, is called the best among them; the remaining groups of sages are equal to the gopikas.",
        '0.45': "(Partly unclear.) The five called sons of the god Agni are Kratu, Sindhu, Shuchi, Pavamana and Kaushika. Tumburu, Urvashi and the hundred, Menaka and the royal sages are equal to the Ajanaja gods (gods by birth); they are called the fathers of the unnamed gods.",
        '0.46': "Lower than the Pavakas (fire-gods) are the unnamed hosts of gods born in the divine clan. Learned in many kinds of knowledge, they daily serve those above them with true devotion and teach those below them the spotless qualities of the Lord who needs no support.",
        '0.47': "Among the gods there are no duties of varna and ashrama, and among themselves they are called incomparable according to taratamya. Among the sages there is the relation of teacher and pupil. The long-lived Pitrs, seven excepted, are called a hundred qualities lower than the Ajanaja gods.",
        '0.48': "(Partly unclear.) Lower than the long-lived Pitrs are the Gandharvas called divine; lower than the emperors are the human Gandharvas; and the best among men are named. In order they are greater by twelve and by eighty-eight qualities, through the strength of the entry of gods.",
        '0.49': "The divine Gandharvas are servants of the gods, and the Gandharvas called human are always instructed by them. The best of men, with nothing but true devotion, worship Shri's Lord, knowing him as the controller of all the senses.",
        '0.50': "In the Bhagavata and other works Badarayana (Vyasa) has stated the differences in many ways, as ten, twelve, twenty-five, a hundred and a thousand-fold, according to the strength of the entry of the higher gods. One should not think this a contradiction; it is accepted by the good.",
        '0.51': "These are said to be fit for liberation: they hear and reflect with the greatest delight and rejoice in what they hear; without seeking the three fruits of dharma, kama and artha, they remember the inner Self of Shri, Vayu and the other gods as the highest, the giver of what the righteous desire.",
        '0.52': "(Partly unclear.) The eternally worldly (nitya-samsari) are made of both qualities and faults. They say that jivas such as Brahma are servants of Hari as of a king; they say that Shiva, Brahma and Vishnu, the three, are equals; and they always ascribe sorrow and joy, birth, death and fear to the incarnations.",
        '0.53': "Without knowledge of taratamya, they daily revile the wise and yet appear among men like good people. Attached to cruel deeds, for the sake of feeding the body they go about the shrines of other deities and the houses of the base.",
        '0.54': "From the ocean of the teaching of Dashapramati (Madhva) I have looked out and taken the gems called \"sumanas\" (the gods), strung them on threads of good vernacular speech, and offered them to Shri's Lord, the Lord of life. May the good be pleased with this always, in their kindness, without counting its faults.",
        '0.55': "(A litany of homage, continued in the next verse.) The incomparable Shri Vishnu, Lakshmi, Brahma, Vayu, Vani, Garuda, the six queens, Parvati, Indra, Kama, Prana, Guru Brihaspati, Pravaha, the Sun, Varuna, Narada, Agni, the seven sages, Mitra, Ganesha, Prithu, Ganga, Svaha, Budha...",
        '0.56': "...Shanaishchara, the Sun's son, Pushkara, the Ajanaja gods, the long-lived Pitrs, the two kinds of Gandharvas, divine and human, the emperors, and those among men called best, middling and lowest: to the four middle and best classes, who stand on the path of liberation (kaivalya), I bow.",
        '0.57': "To the wise who know this extended taratamya with understanding and recite it, the merciful Lord of Rama (Lakshmi), Jagannatha Vithala, the inner Self of Vayu, fulfils the human goals day by day and, knowing their fitness, shows himself in the lotus of their heart.",
      },
    },
    'harikathamrutasara-22': {
      summary: "Sandhi 22 (Sakala-durita-nivarana, the removal of all evils): no one is as merciful as Lakshmi's Lord. The sandhi recalls how he rewarded Kuchela's handful of beaten rice, clothed Draupadi, saved Prahlada, favoured King Tondaman and the potter Bhima, accepted Bali as a devotee, loved the cowherd women, ate at Vidura's house and made a hunter into the sage Valmiki. It explains names by which he dwells in everything (from the Hamsa mantra and others), and says that merely remembering him, or calling \"Hari Vitthala\" for any reason at all, destroys heaps of faults. Worldly happiness is patchy like the shade of a sieve; one should eat what has been offered to Hari, keep the company of devotees and ask only for that company. He is impartial and gives each kind of being its true destination.",
      verses: {
        '0.0': "By the grace of the guru, I shall tell the nectar-essence of Hari's stories; devoted devotees of the Lord, listen to this with reverence.",
        '0.1': "Nowhere do I see anyone as merciful as Lakshmi's Lord. Pleased with Kuchela's beaten rice, he gave him every wealth; the moment she called, he gave garments to Panchali (Draupadi); he tore open the demon's belly and comforted Prahlada: he is an ocean of compassion.",
        '0.2': "When the family of a man named Devasharma, seeing no means of living, cried \"God of gods, our refuge, protect us, protect us\", he heard, was pleased, and protected them, giving happiness by his gracious glance. Petty people wish for happiness without serving him.",
        '0.3': "I see no one in this universe as compassionate as Srinivasa; let the learned search the Shrutis and Puranas and see. Though Drona, Bhishma, Kripa and the others stood in the Kuru army, the Supreme Self did not look at their faults at all and granted them the highest destination.",
        '0.4': "(Partly unclear.) Of fierce valour, he gave his discus and conch to King Tondaman; he was pleased with the clay ornaments of the potter Bhima; though his head was broken, he heeded the words of King Akasha's wife and became the husband of her daughter: he of unfathomable glory, who holds the mace and lotus.",
        '0.5': "When Indra went to Gautama's own wife, he still protected him, and divided into four parts the sin of killing Vritra. And he stood guard at the door of Indra's enemy (Bali), who had carried off his golden crown by a trick, accepting him as a devotee.",
        '0.6': "He was pleased even with the secret love of the women of Nanda's Vraja; the unborn one, father of Brahma, became the tender child of Nandagopa. Free of enmity, he destroyed the demons; and he who rides the king of birds climbed that day on the shoulders of the cowherd boys in Vrindavana.",
        '0.7': "His tender feet are worshipped by Shri's own hands, yet he won the love of the cowherd women of Gokula. Worshipped by Indra, he herded cows and calves. He spurned the Kuru king's meal and accepted Vidura's hospitality, showing himself as eager as a hungry man: so loving is he to his devotees.",
        '0.8': "He became a son to Gopi-devi (Yashoda) and a husband to the women of Vraja; heeding their words he lifted the mountain, he who is full of compassion. Scorcher of foes, he brought and ruled as husband the daughters of the Lord of sacrifice; sustainer of the three worlds, auspicious of body, supremely pure, the friend of the gods.",
        '0.9': "Though without form and name, he let himself be called by the good name that Garga gave him; though all-pervading, he showed himself to people in a limited form. Resolving to torment the demons at the end of the Dvapara age, he whose home is Shvetadvipa came down and protected his own.",
        '0.10': "Praised by Shri, Brahma and the other gods, he took many incarnations and protected gods, sages, kings and men. Ever blissful, he accepts their service and gives its fruits; to devotees such as Sugriva and Dhruva he gave the goals of life.",
        '0.11': "Destroyer of wicked demons, highest of all, full of good qualities, giver of what devotees desire, destroyer of fear, himself free of fear and grief: the maker of creation and destiny knows neither loss nor gain at any time; he who dwells in the cave of the heart is pleased by mere remembrance.",
        '0.12': "Long ago, in the waters of the dissolution, he guarded the frightened lotus-born child (Brahma). Pleased with the one who bore the heavenly river on his head (Shiva), he gave him the rank of his own couch (the position of Shesha). He made the hosts of gods who bowed to him dance with the nectar: ocean of compassion, Lakshmi's beloved, wholly free of care, ever victorious.",
        '0.13': "(Partly unclear.) The Lord acts according to his own true resolve and is called his own servant. Dwelling in the enjoyer and in the things enjoyed, under their names, he is the satisfier who satisfies the lords of the principles; and to the demons, drunk with pride, he gives unfitting fruits.",
        '0.14': "Whether under the pretext of forced labour, or for the sake of the belly, or because of a bad illness, or in mockery, or with a sigh, if one once opens the mouth and says \"Hari, Vitthala, protect me\", the merciful Lord gives his hand and always guards his devotees.",
        '0.15': "On this earth the lotus-eyed Lord protects with his gracious glance the people who praise, in whatever way, the good qualities and deeds of the Lord of Shri and Bhu; and as he was pleased with the monkey Sugriva, he is pleased with them and fulfils their wishes.",
        '0.16': "(Partly unclear.) Lakshmi's Lord, following the deeds of beings, is the one taught by the Shruti passage \"janitotha vishno\"; though birthless, he is born along with us. The son of Akuti (Yajna), when called by his devotees, gives their heart's desire without waiting to be asked.",
        '0.17': "(Names from the Hamsa mantra; partly unclear.) Among men he is called the king who directs their activity (Nrishat); among the gods he is the best (Varasat); in the senses, enjoying their several objects, he is himself called Hota; in the unfailing Veda he is called by the names Rita and Sat. The begetter of the world unceasingly comforts his devotees.",
        '0.18': "(The text of this verse is garbled.) He is called Abja, Goja and Adrija (born of water, of earth, of the mountain). As Abja he is in what is born of water: the conch, nectar, the lotus, Shri and the moon. As Goja he makes sugarcane, plantain, creepers, grass and trees grow. As Adrija he creates gems and beasts.",
        '0.19': "Praised by the Shruti, he dwells everywhere within Bharati's lord (Vayu) and, being called Shuchishat, makes pure the inert and the conscious. Of matchless glory, of endless forms, called Achyuta, in the conscious body he performs all sorts of actions like an ordinary person.",
        '0.20': "(Partly unclear.) In Bharati's lord he is Pranamaya; as Manomaya he causes the thinking of worldly objects; when effort comes, as Vijnanamaya he has it carried through with care; and as Anandamaya he gives happiness in the company of oneself, wife and children.",
        '0.21': "Tell me, you best of brahmins, with guileless minds: how many faults can come to one who is the Self of such forms? Controller of the gunas, he does every work under the name that belongs to it; at the mere remembrance of that God, all the heaps of faults perish.",
        '0.22': "On the earth he is called Kustha; in the circle of the directions, Ashastha; in the sky, Khastha; dwelling in each one separately he is called Vyasta, and in all together, Samasta; being close by, he is called Upastha: the purifier, the pure Self, in the world.",
        '0.23': "In scripture he is called Jnanada (giver of knowledge); in clothing, Manada (giver of honour); in the generous good mind he is called Vadanya (the bountiful). He who rides Garuda abides for ever in each place, acting according to the nature of each.",
        '0.24': "In the village headman he is called Agrani (the leader); among the people, Gramani; in villages and hamlets he is called Shrimanya. The beloved of Shri himself, under the name Yogakshema (gain and safekeeping), protects. Do any of the other gods in the world have this greatness?",
        '0.25': "To the great souls who worship with devotion the form of the Garuda-bannered Lord as Vijaya-sarathi (Arjuna's charioteer), he is gracious everywhere and protects them as the giver of victory. His lotus feet are worshipped by serpent-adorned Shiva; he gives prosperity, has a form that enchants the worlds, and is untouched by any stain.",
        '0.26': "Before creation, the whole host of conscious beings, the gods and the rest, lay in the stream of unwished karma, without tasting its fruits. When the ocean of compassion, together with his consort, created the world, they began to move about, eating the fruits of their own proper and improper deeds.",
        '0.27': "The happiness of worldly life is always like the shade of a sieve; wherever they go it follows the jivas without leaving, and it does not let go even if one says \"I do not want it\". Eat the food offered to Hari and what is left from his worship, keep company with those who know, and throw off the sorrows of worldly life.",
        '0.28': "(Partly unclear.) Pounding, cutting, cooking, storing, burning, giving and touching all bring sin; what Vitthala has eaten and left turns this sin to flour (to nothing). The bad men who leave aside the good and eat in haste only for their own belly, he binds, abuses and thrusts into the furnace in Yama's city.",
        '0.29': "Like the shade of a sieve, worldly happiness surely unsettles a person and is not to be relied on; it is like eating sugar bought on a loan. Do not keep company with the petty; keep company with those who know the good qualities of Shri's beloved, and win the supreme abode.",
        '0.30': "Without delay, give up the desire for enjoyments, and with the greatest love stand at the great door of the house of the Lord who lies on the serpent; bow your head and call: \"Ocean of mercy, medicine for the disease of worldly life, give me your hand!\" The king of the devotees comes quickly.",
        '0.31': "What compassion the treasure of mercy has for his own! Even if true devotees do very low deeds, he accepts them and protects them. To a hunter who killed living beings the son of Dasharatha gave true knowledge and devotion and made him the sage Valmiki: he is supremely merciful.",
        '0.32': "Do not let me, like a foolish man, beg you wretchedly at all times for this and that; let me not ask for the goals of life even in a dream. If you would give something, then in birth after birth, without forgetting, keep me in the company of the devotees who praise your spotless qualities and rejoice.",
        '0.33': "When he who is the form of the four goals of life, the four-formed Lord, is there, do those who know wish for any other goals? The unwise, thinking that worldly happiness is lasting, daily worship other deities, beginning with Ganapati.",
        '0.34': "Honoured by Brahma and the hosts of gods, dwelling in the cave of the heart of all beings, the profound Hari gives all that is sought. In this world and the next, the all-knowing Lord knows the prescribed and unprescribed deeds, stands close by with their fruit, and gives it to everyone.",
        '0.35': "Not even once does the Lord of great glory show partiality, hatred, envy or affection among the jivas. With no motive of his own, at the end of Brahma's age Sri Jagannatha Vithala, who is beyond the reach of the Vedas, simply gives the three kinds of beings each their own true destination.",
      },
    },
  },
};
